uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float2 parallax;
uniform float2 offset;
uniform float strength;
uniform float evolution;
uniform float direction;
uniform float scale;
uniform float2 stretch;
uniform float seed;
uniform float singleAxis;
uniform float screenSpace;
uniform float octaves;
uniform float bias;
float4 permute4(float4 x) {
    x = (x * 34.0 + 1.0) * x;
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}
float snoise(float3 v) {
    float3 i = floor(v + dot(v, float3(1.0 / 3.0)));
    float3 x0 = v - i + dot(i, float3(1.0 / 6.0));
    float3 g = step(x0.yzx, x0.xyz);
    float3 l = 1.0 - g;
    float3 i1 = min(g.xyz, l.zxy);
    float3 i2 = max(g.xyz, l.zxy);
    float3 x1 = x0 - i1 + 1.0 / 6.0;
    float3 x2 = x0 - i2 + 1.0 / 3.0;
    float3 x3 = x0 - 0.5;
    i = i - floor(i * (1.0 / 289.0)) * 289.0;
    float4 p = permute4(permute4(permute4(i.z + float4(0.0, i1.z, i2.z, 1.0)) + i.y + float4(0.0, i1.y, i2.y, 1.0)) + i.x + float4(0.0, i1.x, i2.x, 1.0));
    float n7 = 0.142857142857;
    float4 j = p - 49.0 * floor(p * n7 * n7);
    float4 gx = floor(j * n7);
    float4 gy = floor(j - 7.0 * gx);
    float4 x = gx * (2.0 * n7) + (0.5 * n7 - 1.0);
    float4 y = gy * (2.0 * n7) + (0.5 * n7 - 1.0);
    float4 h = 1.0 - abs(x) - abs(y);
    float4 b0 = float4(x.xy, y.xy);
    float4 b1 = float4(x.zw, y.zw);
    float4 s0 = floor(b0) * 2.0 + 1.0;
    float4 s1 = floor(b1) * 2.0 + 1.0;
    float4 sh = -step(h, float4(0.0));
    float4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    float4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
    float3 p0 = float3(a0.xy, h.x);
    float3 p1 = float3(a0.zw, h.y);
    float3 p2 = float3(a1.xy, h.z);
    float3 p3 = float3(a1.zw, h.w);
    float4 norm = 1.79284291400159 - 0.85373472095314 * float4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3));
    float4 m = max(0.6 - float4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m * m, float4(dot(p0, x0) * norm.x, dot(p1, x1) * norm.y, dot(p2, x2) * norm.z, dot(p3, x3) * norm.w));
}
float turb(float2 q, float z, float octaves, float2 drift) {
    float t = 0.0;
    float amp = 1.0;
    float f = 1.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= floor(octaves)) break;
        t += amp * abs(snoise(float3(q * f + drift * float(i), z)));
        amp *= 0.5;
        f *= 2.0;
    }
    return t;
}
float2 flow(float2 coord, float2 dims, float mode, float2 sc, float z, float octaves, float amount, float lift, float2 shift, float2 drift) {
    float2 c = float2(coord.x - dims.x * 0.5 - shift.x, dims.y * 0.5 - coord.y + shift.y) / dims.y;
    float r = length(c);
    float2 uvc = float2(c.x * dims.y / dims.x, c.y);
    float2 d = float2(0.0);
    if (mode < 0.5) {
        d = float2(amount * (turb(0.5 + (float2(0.0, c.y) - 0.5) / sc, z, octaves, drift) - 0.5 + lift), 0.0);
    } else if (mode < 1.5) {
        d = float2(0.0, amount * (turb(0.5 + (float2(c.x, 0.0) - 0.5) / sc, z, octaves, drift) - 0.5 + lift));
    } else if (mode < 2.5) {
        d = amount * (float2(turb(0.5 + (c - 0.5) / sc, z, octaves, drift), turb(0.5 + (c.yx - 0.5) / sc, z, octaves, drift)) - 0.5 + lift);
    } else if (mode < 3.5) {
        float a = r > 0.0 ? acos(clamp(c.y / r, -1.0, 1.0)) / 3.14159265 : 0.0;
        d = (length(uvc) > 0.0 ? normalize(uvc) : float2(0.0, 1.0)) * amount * (turb(0.5 + (float2(a, 0.0) - 0.5) / sc, z, octaves, drift) - 0.5 + lift);
    } else {
        float spin = amount * (turb(0.5 + (float2(0.0, r) - 0.5) / sc, z, octaves, drift) - 0.5 + lift);
        float2 turned = float2(c.x * cos(spin) - c.y * sin(spin), c.x * sin(spin) + c.y * cos(spin)) - c;
        d = float2(turned.x * dims.y / dims.x, turned.y);
    }
    return d * float2(dims.x, -dims.y);
}
half4 main(float2 coord) {
    float2 dims = screenSpace > 0.5 ? screen.zw : size;
    float2 at = screenSpace > 0.5 ? coord - screen.xy : coord;
    float2 d = flow(at, dims, direction, max(scale, 0.01) / max(abs(stretch), float2(0.01)), evolution + seed * 11.9, octaves, strength, bias, offset, float2(-parallax.x, parallax.y) / (dims.y * max(scale, 0.01)));
    float2 lo = screen.xy + 0.5;
    float2 hi = screen.xy + screen.zw - 0.5;
    half4 sum = half4(0.0);
    for (int i = 0; i < 48; i++) {
        sum += image.eval(clamp(coord + d * ((float(i) + 0.5) / 48.0), lo, hi));
    }
    return sum / 48.0;
}
